-- HostelHub V21: Create allocations
-- Do not edit or rerun previously applied migrations.

CREATE TABLE public.allocations (
                                    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

                                    hostel_id BIGINT NOT NULL,
                                    hostler_id BIGINT NOT NULL,
                                    bed_id BIGINT NOT NULL,
                                    allocated_by BIGINT NOT NULL,

                                    status VARCHAR(20) NOT NULL DEFAULT 'RESERVED',

                                    start_date DATE NOT NULL,
                                    end_date DATE,

                                    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

                                    CONSTRAINT fk_allocations_hostel
                                        FOREIGN KEY (hostel_id)
                                            REFERENCES public.hostels(id)
                                            ON DELETE RESTRICT,

                                    CONSTRAINT fk_allocations_hostler
                                        FOREIGN KEY (hostler_id)
                                            REFERENCES public.users(id)
                                            ON DELETE RESTRICT,

                                    CONSTRAINT fk_allocations_bed
                                        FOREIGN KEY (bed_id)
                                            REFERENCES public.beds(id)
                                            ON DELETE RESTRICT,

                                    CONSTRAINT fk_allocations_allocated_by
                                        FOREIGN KEY (allocated_by)
                                            REFERENCES public.users(id)
                                            ON DELETE RESTRICT,

                                    CONSTRAINT chk_allocations_status
                                        CHECK (status IN ('RESERVED', 'ACTIVE', 'COMPLETED', 'CANCELLED')),

                                    CONSTRAINT chk_allocations_dates
                                        CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX idx_allocation_hostler
    ON public.allocations(hostler_id);

CREATE INDEX idx_allocation_hostel_status
    ON public.allocations(hostel_id, status);

CREATE INDEX idx_allocation_bed_status
    ON public.allocations(bed_id, status);

-- A bed can have only one RESERVED or ACTIVE allocation at a time.
CREATE UNIQUE INDEX uq_allocations_bed_reserved_active
    ON public.allocations(bed_id)
    WHERE status IN ('RESERVED', 'ACTIVE');